insert into sys_user_access_token (
    user_id, name, token_hash, token_prefix, source, client_id, grant_id, resource,
    expires_at, create_time
) values (
    #{userId}, #{name}, #{tokenHash}, #{tokenPrefix}, #{source}, #{clientId}, #{grantId}, #{resource},
    #{expiresAt}, #{createTime}
)
